-- =========================
-- Window rules (user)
-- Hyprland 0.53+ (new syntax)
-- =========================

-- eww syna-dashboard - no compositor rounding (use CSS instead)
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.window_rule({
    match = {
        class = "^(eww)$",
    },
    rounding = 0,
})

-- Chromium → workspace 2 (runtime/manual launches)
--windowrule = workspace 2 silent, match:initialClass ^(chromium|google-chrome|brave)$

-- btop → workspace 4
--windowrule = workspace 4 silent, match:class ^(ghostty)$, match:title ^(btop)

-- Waydroid - fullscreen on primary monitor
hl.window_rule({
    name = "waydroid",
    match = {
        class = "^(Waydroid)$",
    },
    workspace = "3",
    size = "2560 1440",
    center = true,
    fullscreen = true,
    fullscreen_state = "2 2",
    no_blur = true,
    idle_inhibit = "always",
})

hl.window_rule({
    match = {
        class = "^([Ss]team)$",
    },
    workspace = "3",
})

hl.window_rule({
    match = {
        class = "^(steam)$",
        title = "^(Steam Big Picture Mode)$",
    },
    fullscreen = true,
})

hl.window_rule({
    name = "steam-games",
    match = {
        class = "^(steam_app_[0-9]+)$",
    },
    workspace = "3",
    opacity = "1 1",
    no_blur = true,
    idle_inhibit = "fullscreen",
})

hl.window_rule({
    match = {
        class = "^(com[.]moonlight_stream[.]Moonlight|[Mm]oonlight)$",
    },
    workspace = "3",
})

hl.window_rule({
    name = "gamescope-gaming",
    match = {
        class = "^(gamescope)$",
    },
    workspace = "3",
    fullscreen = true,
    opacity = "1 1",
    no_blur = true,
    idle_inhibit = "fullscreen",
})

hl.window_rule({
    match = {
        class = "^(com[.]mitchellh[.]ghostty|ghostty)$",
    },
    opacity = "1.0 override 1.0 override",
    no_blur = true,
})

hl.window_rule({
    match = {
        class = "^(syna-theme-picker.*)$",
    },
    float = true,
    size = "860 740",
    center = true,
    opacity = "1 override 1 override",
})

hl.config({
    xwayland = {
        force_zero_scaling = true,
    },
    -- Steam and games use workspace 3, mapped to the primary monitor locally.
    -- Include startup/loading windows and dialogs, whose titles vary.
    -- Moonlight launcher and streams use the primary gaming workspace.
    -- Route the outer Gamescope window as well as native Steam game windows.
    -- Keep terminal text and theme backgrounds solid in every desktop theme.
    -- Theme chooser: show an opaque centered preview without rearranging terminals.
})

